import { useEffect, useMemo, useRef, useState } from 'react'

const loadInstagramScriptOnce = (() => {
  let loaded = false
  return () => {
    if (loaded) return
    const s = document.createElement('script')
    s.src = 'https://www.instagram.com/embed.js'
    s.async = true
    document.body.appendChild(s)
    loaded = true
  }
})()

export default function InstagramReels({
  api = '/api/instagram/reels',
  limit = 6,
}) {
  const [reels, setReels] = useState([])
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState(null)
  const rendered = useRef(false)

  useEffect(() => {
    let cancelled = false

    async function go() {
      setLoading(true)
      setError(null)
      try {
        const res = await fetch(api)
        if (!res.ok) throw new Error(`HTTP ${res.status}`)
        const data = await res.json()
        // Expecting: [{ id, permalink, thumbnail_url, caption, timestamp }]
        const items = (data || []).filter((m) => m.permalink).slice(0, limit)
        if (!cancelled) setReels(items)
      } catch (e) {
        if (!cancelled) setError(e.message || 'Failed to load reels')
      } finally {
        if (!cancelled) setLoading(false)
      }
    }

    go()
    return () => {
      cancelled = true
    }
  }, [api, limit])

  // When reels change, (re)load embed script so Instagram upgrades iframes/blocks
  useEffect(() => {
    // Prefer iframe embeds (no script needed), but load script in case we switch.
    loadInstagramScriptOnce()
    // Try to reprocess embeds if Instagram script is present
    if (window.instgrm?.Embeds?.process) {
      // Delay to ensure DOM is committed
      const t = setTimeout(() => window.instgrm.Embeds.process(), 0)
      return () => clearTimeout(t)
    }
  }, [reels])

  const gridCols = useMemo(
    () => 'grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6',
    []
  )

  return (
    <section id='reels' className='py-16 bg-neutral-950'>
      <div className='container mx-auto px-6'>
        <div className='text-center mb-10'>
          <h2 className='text-3xl md:text-4xl font-normal uppercase tracking-tight text-neutral-100'>
            Latest <span className='text-orange-200'>Reels</span>
          </h2>
          <p className='text-neutral-400 mt-2'>
            From <span className='text-neutral-100'>@excelaesthetics1</span>
          </p>
        </div>

        {error && (
          <div className='max-w-2xl mx-auto mb-6 rounded border border-red-500/40 bg-red-500/10 text-red-200 px-4 py-3 text-sm'>
            Couldn’t load reels ({error}). We’ll try again soon.
          </div>
        )}

        {loading ? (
          <div className={gridCols}>
            {Array.from({ length: 6 }).map((_, i) => (
              <div
                key={i}
                className='aspect-[9/16] rounded-sm bg-neutral-900 animate-pulse'
              />
            ))}
          </div>
        ) : (
          <div className={gridCols}>
            {reels.map((m) => {
              // Instagram supports iframe embeds via `${permalink}embed`
              const src = m.permalink.endsWith('/')
                ? `${m.permalink}embed`
                : `${m.permalink}/embed`
              return (
                <div
                  key={m.id}
                  className='rounded-sm overflow-hidden border border-neutral-800 bg-neutral-900'
                >
                  <div className='aspect-[9/16]'>
                    <iframe
                      title={m.id}
                      src={src}
                      className='w-full h-full'
                      allow='autoplay; clipboard-write; encrypted-media; picture-in-picture; web-share'
                      allowFullScreen
                      loading='lazy'
                    />
                  </div>
                  <div className='px-4 py-3 text-xs text-neutral-400 border-t border-neutral-800'>
                    {m.caption ? m.caption.slice(0, 100) : 'Instagram Reel'}
                    {m.caption && m.caption.length > 100 ? '…' : ''}
                  </div>
                </div>
              )
            })}
          </div>
        )}

        <div className='text-center mt-10'>
          <a
            href='https://www.instagram.com/excelaesthetics1/'
            target='_blank'
            rel='noopener noreferrer'
            className='inline-block border border-neutral-700 text-neutral-100 hover:bg-neutral-900 uppercase tracking-wider text-sm px-8 py-3 transition-colors'
          >
            View on Instagram
          </a>
        </div>
      </div>
    </section>
  )
}
